const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto'),zlib=require('node:zlib');
const manifest=require('../bootstrap/manifest.json');const archive=fs.readFileSync(path.join(__dirname,'../bootstrap/knowledge-v1.json.gz'));if(crypto.createHash('sha256').update(archive).digest('hex')!==manifest.compressedSha256)throw Error('Bootstrap archive checksum mismatch');const bytes=zlib.gunzipSync(archive);if(crypto.createHash('sha256').update(bytes).digest('hex')!==manifest.sha256)throw Error('Bootstrap checksum mismatch');const records=JSON.parse(bytes);if(records.length!==manifest.records)throw Error('Bootstrap count mismatch');module.exports={records,manifest};
